document.write('<script src="matter-core.min.js"><\/script>');
(function(){
  const style=document.createElement('style');
  style.textContent=`#modeOverlay{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;background:#0a1b32f7;padding:20px;color:#eaffff}.mode-title{font:700 19px Consolas,monospace;letter-spacing:3px;color:#dffcff}.mode-sub{font:10px Consolas,"Microsoft YaHei",monospace;letter-spacing:2px;color:#7bd6e6}.mode-options{display:flex;flex-direction:column;gap:9px;width:min(78%,240px);margin:4px 0}.mode-option{min-height:48px;border:1px solid #52798d;border-radius:6px;background:#102943;color:#9dbdca;font:700 12px Consolas,"Microsoft YaHei",monospace;letter-spacing:1.5px;text-align:left;padding:8px 14px;box-shadow:none}.mode-option b{color:#eaffff;font-size:14px}.mode-option small{display:block;font-size:8px;color:#7699aa;margin:4px 0 0 21px;letter-spacing:1px}.mode-option.selected{border-color:#aef8ff;background:#123952;color:#8eeaf2;box-shadow:0 0 14px #43d4fe33}.mode-option.selected b{color:#cfffff}.mode-enter{border:1px solid #c1fcff;border-radius:30px;min-height:44px;padding:10px 22px;background:#8ae5ef;color:#113e57;font:800 12px "Microsoft YaHei",sans-serif;margin-top:4px;box-shadow:0 3px 0 #3c8aab}.change-mode{border:0!important;background:transparent!important;box-shadow:none!important;color:#8dc6d6!important;font:9px Consolas,"Microsoft YaHei",monospace!important;letter-spacing:1px;padding:7px 10px!important;min-height:30px!important;margin-top:0!important}@media(max-height:560px) and (min-width:600px){#modeOverlay{gap:6px;padding:7px}.mode-title{font-size:13px}.mode-sub{font-size:7px}.mode-options{gap:4px;margin:0}.mode-option{min-height:34px;padding:4px 10px;font-size:9px}.mode-option b{font-size:10px}.mode-option small{font-size:6px;margin-top:2px}.mode-enter{min-height:34px;padding:5px 14px;font-size:9px}}`;
  document.head.appendChild(style);

  const stage=document.querySelector('.stage');
  if(!stage)return;
  const mode=document.createElement('div');
  mode.id='modeOverlay';
  mode.setAttribute('role','dialog');
  mode.setAttribute('aria-modal','true');
  mode.innerHTML='<span class="mode-sub">SELECT YOUR MEMORY</span><div class="mode-title">MEMORY MODE</div><div class="mode-sub">选择模式</div><div class="mode-options"><button class="mode-option" data-levels="9"><span>○</span> <b>EASY</b>　简单<small>9 LEVELS · 轻松抵达记忆终点</small></button><button class="mode-option selected" data-levels="11"><span>●</span> <b>HARD</b>　困难<small>11 LEVELS · 原版挑战</small></button></div><button class="mode-enter" type="button">ENTER MEMORY →</button>';
  stage.appendChild(mode);

  let chosen=11;
  const options=[...mode.querySelectorAll('.mode-option')];
  function select(levels){
    chosen=levels;
    options.forEach(btn=>{
      const active=Number(btn.dataset.levels)===levels;
      btn.classList.toggle('selected',active);
      btn.querySelector('span').textContent=active?'●':'○';
    });
  }
  options.forEach(btn=>btn.addEventListener('click',()=>select(Number(btn.dataset.levels))));

  function showMode(){
    try{running=false;cancelAnimationFrame(gameRAF);loadingToken++;}catch(_){ }
    ['overlay','winOverlay','loadingOverlay'].forEach(id=>{const el=document.getElementById(id);if(el)el.style.display='none';});
    mode.style.display='flex';
  }
  function begin(){
    window.__memoryModeLevels=chosen;
    try{
      pickLevels=function(){return [...shuffle(RANDOM_POOL.slice()).slice(0,window.__memoryModeLevels-1),FINAL_PHOTO];};
      const cap=document.querySelector('.screen-caption span:last-child');
      if(cap)cap.textContent=chosen+' LEVELS';
      mode.style.display='none';
      startGame();
    }catch(e){
      console.error(e);
      mode.style.display='flex';
    }
  }
  mode.querySelector('.mode-enter').addEventListener('click',begin);

  function addChangeButton(parentId){
    const parent=document.getElementById(parentId);
    if(!parent||parent.querySelector('.change-mode'))return;
    const btn=document.createElement('button');
    btn.type='button';btn.className='change-mode';btn.textContent='CHANGE MODE / 切换模式';
    btn.addEventListener('click',showMode);
    parent.appendChild(btn);
  }
  addChangeButton('overlay');
  addChangeButton('winOverlay');
})();